-- Captured from Room version 4 generated schema.
CREATE TABLE IF NOT EXISTS `students` (`id` TEXT NOT NULL, `fullName` TEXT NOT NULL, `email` TEXT NOT NULL, `passwordHash` TEXT NOT NULL, `profilePictureUrl` TEXT, `status` TEXT NOT NULL, `studentType` TEXT NOT NULL, `institutionId` TEXT, `micSensitivity` REAL NOT NULL, `audioQuality` TEXT NOT NULL, `dataPrivacyOptOut` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `index_students_email` ON `students` (`email`);
CREATE INDEX IF NOT EXISTS `index_students_institutionId` ON `students` (`institutionId`);
CREATE TABLE IF NOT EXISTS `vocal_coaches` (`id` TEXT NOT NULL, `fullName` TEXT NOT NULL, `email` TEXT NOT NULL, `status` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `institutions` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `address` TEXT NOT NULL, `contactEmail` TEXT NOT NULL, `status` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `vocal_lessons` (`id` TEXT NOT NULL, `coachId` TEXT, `title` TEXT NOT NULL, `description` TEXT NOT NULL, `difficultyLevel` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_vocal_lessons_coachId` ON `vocal_lessons` (`coachId`);
CREATE TABLE IF NOT EXISTS `vocal_exercises` (`id` TEXT NOT NULL, `coachId` TEXT, `title` TEXT NOT NULL, `description` TEXT NOT NULL, `difficultyLevel` TEXT NOT NULL, `targetNote` TEXT NOT NULL, `targetFrequencyHz` REAL NOT NULL, `referencePitchData` TEXT, `referenceToneData` TEXT, `audioSampleUrl` TEXT, `durationSeconds` INTEGER NOT NULL, `orderIndex` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_vocal_exercises_coachId` ON `vocal_exercises` (`coachId`);
CREATE TABLE IF NOT EXISTS `lesson_exercises` (`id` TEXT NOT NULL, `lessonId` TEXT NOT NULL, `exerciseId` TEXT NOT NULL, `orderIndex` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_lesson_exercises_lessonId` ON `lesson_exercises` (`lessonId`);
CREATE INDEX IF NOT EXISTS `index_lesson_exercises_exerciseId` ON `lesson_exercises` (`exerciseId`);
CREATE TABLE IF NOT EXISTS `practice_sessions` (`id` TEXT NOT NULL, `studentId` TEXT NOT NULL, `exerciseId` TEXT NOT NULL, `status` TEXT NOT NULL, `bestScore` REAL NOT NULL, `unlockedAt` INTEGER NOT NULL, `completedAt` INTEGER, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_practice_sessions_studentId` ON `practice_sessions` (`studentId`);
CREATE INDEX IF NOT EXISTS `index_practice_sessions_exerciseId` ON `practice_sessions` (`exerciseId`);
CREATE UNIQUE INDEX IF NOT EXISTS `index_practice_sessions_studentId_exerciseId` ON `practice_sessions` (`studentId`, `exerciseId`);
CREATE TABLE IF NOT EXISTS `practice_attempts` (`id` TEXT NOT NULL, `studentId` TEXT NOT NULL, `exerciseId` TEXT NOT NULL, `audioRecordingUrl` TEXT NOT NULL, `durationSeconds` INTEGER NOT NULL, `isSynced` INTEGER NOT NULL, `recordedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_practice_attempts_studentId` ON `practice_attempts` (`studentId`);
CREATE INDEX IF NOT EXISTS `index_practice_attempts_exerciseId` ON `practice_attempts` (`exerciseId`);
CREATE TABLE IF NOT EXISTS `analysis_results` (`id` TEXT NOT NULL, `practiceAttemptId` TEXT NOT NULL, `accuracyScore` REAL NOT NULL, `toneScore` REAL NOT NULL, `overallScore` REAL NOT NULL, `spectrogramUrl` TEXT, `detectedPitchData` TEXT NOT NULL, `feedbackNotes` TEXT NOT NULL, `verdictStatus` TEXT NOT NULL, `isSynced` INTEGER NOT NULL, `analyzedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `index_analysis_results_practiceAttemptId` ON `analysis_results` (`practiceAttemptId`);
CREATE TABLE IF NOT EXISTS `progress_reports` (`id` TEXT NOT NULL, `studentId` TEXT NOT NULL, `averageAccuracy` REAL NOT NULL, `totalSessions` INTEGER NOT NULL, `totalDurationSeconds` INTEGER NOT NULL, `isSynced` INTEGER NOT NULL, `generatedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_progress_reports_studentId` ON `progress_reports` (`studentId`);
CREATE TABLE IF NOT EXISTS `achievements` (`id` TEXT NOT NULL, `title` TEXT NOT NULL, `description` TEXT NOT NULL, `criteriaType` TEXT NOT NULL, `criteriaValue` INTEGER NOT NULL, `badgeIconUrl` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `student_achievements` (`id` TEXT NOT NULL, `studentId` TEXT NOT NULL, `achievementId` TEXT NOT NULL, `earnedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_student_achievements_studentId` ON `student_achievements` (`studentId`);
CREATE INDEX IF NOT EXISTS `index_student_achievements_achievementId` ON `student_achievements` (`achievementId`);
CREATE UNIQUE INDEX IF NOT EXISTS `index_student_achievements_studentId_achievementId` ON `student_achievements` (`studentId`, `achievementId`);
CREATE TABLE IF NOT EXISTS `notifications` (`id` TEXT NOT NULL, `studentId` TEXT NOT NULL, `title` TEXT NOT NULL, `message` TEXT NOT NULL, `isRead` INTEGER NOT NULL, `sentAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_notifications_studentId` ON `notifications` (`studentId`);
CREATE TABLE IF NOT EXISTS `subscriptions` (`id` TEXT NOT NULL, `studentId` TEXT NOT NULL, `paymentId` TEXT, `planType` TEXT NOT NULL, `status` TEXT NOT NULL, `startDate` INTEGER NOT NULL, `endDate` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_subscriptions_studentId` ON `subscriptions` (`studentId`);
CREATE TABLE IF NOT EXISTS `student_feature_access` (`id` TEXT NOT NULL, `studentId` TEXT NOT NULL, `featureId` TEXT NOT NULL, `accessStatus` TEXT NOT NULL, `unlockedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_student_feature_access_studentId` ON `student_feature_access` (`studentId`);
CREATE UNIQUE INDEX IF NOT EXISTS `index_student_feature_access_studentId_featureId` ON `student_feature_access` (`studentId`, `featureId`);
CREATE TABLE IF NOT EXISTS `reminder_settings` (`studentId` TEXT NOT NULL, `enabled` INTEGER NOT NULL, `hourOfDay` INTEGER NOT NULL, `minuteOfHour` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`studentId`));
